proxy.caddy:
# Caddy reference config for ubooquity, generated by the hub from its image.yml.
# Caddy and the ubooquity container share a docker network; replace example.com with your domain.
# Caddy fetches the certificate and passes websockets through on its own.

ubooquity.example.com {
	handle /admin* {
		reverse_proxy ubooquity:2203
	}

	handle /admin-res* {
		reverse_proxy ubooquity:2203
	}

	handle /admin-api* {
		reverse_proxy ubooquity:2203
	}

	handle {
